import numpy as np

def make_prices(n=750, seed=21, mu=0.0003, sigma=0.012):
    """n + 1 daily closes from 100: daily log returns mu + sigma * noise."""
    rng = np.random.default_rng(seed)
    r = mu + sigma * rng.standard_normal(n)
    return np.round(100 * np.exp(np.concatenate([[0.0], np.cumsum(r)])), 4).tolist()

def make_regime_prices(n=500, seed=11, calm=0.006, wild=0.02):
    """n + 1 closes: calm for the first half, wild for the second."""
    rng = np.random.default_rng(seed)
    sig = np.where(np.arange(n) < n // 2, calm, wild)
    r = 0.0002 + sig * rng.standard_normal(n)
    return np.round(100 * np.exp(np.concatenate([[0.0], np.cumsum(r)])), 4).tolist()

def log_returns(prices):
    """Daily log returns: entry t is ln(P[t+1] / P[t])."""
    p = np.asarray(prices, dtype=float)
    return np.round(np.diff(np.log(p)), 8).tolist()

def rolling_vol(prices, window=20):
    """vol[t]: sample sd of the last `window` simple returns ending on day t (nan before)."""
    p = np.asarray(prices, dtype=float)
    r = p[1:] / p[:-1] - 1
    vol = [float('nan')] * len(p)
    for t in range(window, len(p)):
        vol[t] = float(np.std(r[t - window:t], ddof=1))
    return vol

def _touch(path, upper, lower, h):
    for d in range(1, min(h, len(path) - 1) + 1):
        if path[d] <= lower:
            return (-1, d)
        if path[d] >= upper:
            return (1, d)
    return (0, min(h, len(path) - 1))

def tb_events(prices, vol, k, h, start):
    """(label, days to touch) for entries start .. len(prices) - h - 1."""
    return [_touch(prices[t:t + h + 1], prices[t] * (1 + k * vol[t]),
                   prices[t] * (1 - k * vol[t]), h) for t in range(start, len(prices) - h)]

def label_windows(seed=21, k=2, h=10, n=1000):
    """Triple-barrier labels on make_prices(n, seed) with rolling_vol(p, 20).
    Returns starts, ends (entry day and first-touch day, inclusive), labels, n_days."""
    p = make_prices(n, seed)
    v = rolling_vol(p, 20)
    ev = tb_events(p, v, k, h, 20)
    starts = list(range(20, 20 + len(ev)))
    ends = [s + d for s, (lab, d) in zip(starts, ev)]
    return starts, ends, [lab for lab, d in ev], len(p)

