widget.solution:
import math

def effective_n(weights):
    return round(sum(weights), 4)

def weighted_hit_rate_se(hits, weights):
    n_eff = sum(weights)
    p = sum(w * h for w, h in zip(weights, hits)) / n_eff
    se = math.sqrt(p * (1 - p) / n_eff)
    return (round(p, 4), round(se, 4))
